def create_native_ententes(apps, schema_editor):
    # For the commandants created before the ententes
    Entente = apps.get_model('game', 'Entente')
    EntenteMember = apps.get_model('game', 'EntenteMember')

    for commandant in apps.get_model('game', 'Commandant').objects.exclude(native_sector=''):
        entente = Entente.objects.get_or_create(native_sector=commandant.native_sector,
                                                defaults={'category': 'native', 'creation_date': timezone.now()})[0]
        EntenteMember.objects.create(entente=entente, commandant=commandant, status='member', datetime=commandant.creation_date)
        commandant.native_entente = entente
        commandant.save(update_fields=['native_entente'])


